def transform(grid):
    h, w = len(grid), len(grid[0])

    def get_bands(length, is_separator):
        bands = []
        start = 0
        for i in range(length):
            if is_separator(i):
                if start < i:
                    bands.append(list(range(start, i)))
                start = i + 1
        if start < length:
            bands.append(list(range(start, length)))
        if not bands:
            return bands
        sizes = [len(b) for b in bands]
        normal = max(set(sizes), key=sizes.count)
        return [b for b in bands if len(b) == normal]

    row_bands = get_bands(h, lambda r: all(x == 8 for x in grid[r]))
    col_bands = get_bands(w, lambda c: all(grid[r][c] == 8 for r in range(h)))

    marks = {2: [], 3: []}
    for ri, rs in enumerate(row_bands):
        for ci, cs in enumerate(col_bands):
            for r in rs:
                for c in cs:
                    if grid[r][c] in marks:
                        marks[grid[r][c]].append((ri, ci))

    tiles = {2: set(), 3: set()}
    for color, points in marks.items():
        # Connect markers aligned within the same tile row or column.
        for r1, c1 in points:
            for r2, c2 in points:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        tiles[color].add((r1, c))
                if c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        tiles[color].add((r, c1))

    out = [row[:] for row in grid]
    for ri, rs in enumerate(row_bands):
        for ci, cs in enumerate(col_bands):
            a, b = (ri, ci) in tiles[2], (ri, ci) in tiles[3]
            color = 6 if a and b else (2 if a else (3 if b else None))
            if color is not None:
                for r in rs:
                    for c in cs:
                        out[r][c] = color
    return out
